frontend/ClearButton.vue<pre><code>&lt;template&gt;
  &lt;ToolbarButton tooltip="Clear all notes" shortcut="N" @click="clear"&gt;
    &lt;Eraser /&gt;
  &lt;/ToolbarButton&gt;
&lt;/template&gt;

&lt;script setup lang="ts"&gt;
import {
  ToolbarButton,
  useChannel,
  useShortcuts,
} from "@compas-dev/compas-threejs-ts";
import { Eraser } from "lucide-vue-next";

const channel = useChannel("notes");
const clear = () =&gt; channel.send("clear");

useShortcuts({ n: clear });
&lt;/script&gt;
</code></pre> <p><code>ToolbarButton</code> looks like the viewer's own buttons, shows the tooltip with the shortcut, and greys itself out when Python disables it. <code>useShortcuts</code> binds lower-case <code>event.key</code>s while the component is mounted; it stands down while the button is disabled, while the user types in a field, and while another plugin holds input (a drawing tool, for instance). <code>useChannel</code> is the component version of <code>viewer.channel</code>: its <code>on</code> handlers are removed with the component.</p>

frontend/NoteAction.vue<pre><code>&lt;template&gt;
  &lt;Button variant="secondary" class="w-full" @click="edit"&gt;
    &lt;StickyNote class="size-4" /&gt;
    {{ current ? "Edit note" : "Add note" }}
  &lt;/Button&gt;
&lt;/template&gt;

&lt;script setup lang="ts"&gt;
import { Button, useChannel, useViewer } from "@compas-dev/compas-threejs-ts";
import { StickyNote } from "lucide-vue-next";
import { computed } from "vue";

import { notes } from "./notes";

const viewer = useViewer();
const channel = useChannel("notes");

// The picked object's note, if it has one.
const current = computed(() =&gt; {
  const guid = viewer.state.selectedGuid.value;
  return notes.value.find((note) =&gt; note.guid === guid);
});

function edit() {
  const guid = viewer.state.selectedGuid.value;
  if (!guid) return;
  const text = window.prompt("Note", current.value?.text ?? "");
  if (text === null) return;
  // Python stores it and sends the new list back; an empty text deletes the note.
  channel.send("write", { guid, text });
}
&lt;/script&gt;
</code></pre> <p>The component doesn't update <code>notes</code> itself: it sends the request and waits for Python's answer. That round trip is fast, and it means there is only one source of truth.</p>

frontend/NotesPanel.vue<pre><code>&lt;template&gt;
  &lt;p v-if="!notes.length" class="text-muted-foreground text-sm"&gt;
    No notes yet: pick an object and add one.
  &lt;/p&gt;
  &lt;ul v-else class="flex flex-col gap-2 text-sm"&gt;
    &lt;li
      v-for="note in notes"
      :key="note.guid"
      class="rounded-md px-2 py-1"
      :class="{ 'bg-secondary': note.guid === selected }"
    &gt;
      &lt;div class="text-muted-foreground text-xs"&gt;{{ note.name }}&lt;/div&gt;
      {{ note.text }}
    &lt;/li&gt;
  &lt;/ul&gt;
&lt;/template&gt;

&lt;script setup lang="ts"&gt;
import { useViewer } from "@compas-dev/compas-threejs-ts";
import { computed } from "vue";

import { notes } from "./notes";

const viewer = useViewer();
const selected = computed(() =&gt; viewer.state.selectedGuid.value);
&lt;/script&gt;
</code></pre> <p><code>viewer.state</code> is reactive, so the picked object's note is highlighted as the selection changes.</p>
